import json, sys, os, base64
from playwright.sync_api import sync_playwright
fx = json.load(open('/tmp/fixtures_v38.json')); gid = fx['gid']
errors = []; passed = 0; failed = 0
SHOTS = sys.argv[1] if len(sys.argv) > 1 else None
def ok(c, msg):
    global passed, failed
    if c: passed += 1; print('  ✓', msg)
    else: failed += 1; print('  ✗ FAIL:', msg)
def emit(page, ev, data): page.evaluate("([e,d]) => window.__srv.emit(e,d)", [ev, data])
def sent(page, name): return page.evaluate("(n) => (window.__sent||[]).filter(x => x[0]===n).map(x => x[1])", name)
def clear(page): page.evaluate("() => { window.__sent = []; }")
def shot(page, name):
    if SHOTS: page.screenshot(path=f'{SHOTS}/{name}.png')
def route_block(page):
    for pat in ('**/cdnjs.cloudflare.com/**', '**/flagcdn.com/**', '**/fonts.googleapis.com/**', '**/fonts.gstatic.com/**'): page.route(pat, lambda r: r.abort())
def watch(page, tag):
    page.on('pageerror', lambda e: errors.append(tag + ' PAGEERROR ' + str(e)))
def box(page, sel): return page.evaluate("(s) => { const r = document.querySelector(s).getBoundingClientRect(); return {x: r.x, y: r.y, w: r.width, h: r.height, r: r.right, b: r.bottom} }", sel)
LED = {'currency': 'USD', 'totalDeposited': 100020, 'moneyIn': 100020, 'moneyOut': 20, 'fees': 20, 'withdrawn': 0, 'inProgress': 0, 'held': 0, 'available': 100000, 'other': 0, 'reconciles': True,
       'feeItems': [{'kind': 'card_fee', 'title': 'AIRWX card issuing fee', 'amount': 20, 'date': '2026-10-22T10:01:00Z', 'ref': 'CF-1'}]}
ACCT = {**fx['verified'], 'countryIso': 'GH', 'balances': {'available': 100000, 'held': 0, 'pending': 0, 'totalDeposited': 100020}, 'ledger': LED}
INC = [{'id': 'i1', 'ref': 'IN-1001', 'payerName': 'Acme Ltd', 'purpose': 'Order 55', 'amount': 100020, 'amountCurrency': 'USD', 'amountLedger': 100020, 'status': 'credited', 'receivedAt': '2026-10-22T09:00:00Z', 'feeAmount': 0,
        'receivedInto': {'label': 'USD account ••7765', 'idLabel': 'Account number ••7765', 'accountId': '48213907765'}, 'receiptUrl': '/receipt/1'}]
WD = [{'id': 'w1', 'ref': 'WD-1', 'method': 'bank', 'bankName': 'Test Bank', 'bankAccount': '123456789012', 'amount': 500, 'amountCurrency': 'USD', 'amountLedger': 500, 'status': 'pending', 'createdAt': '2026-10-23T08:00:00Z'}]
PNG = base64.b64decode('iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mP8z8BQDwAEhQGAhKmMIQAAAABJRU5ErkJggg==')

with sync_playwright() as p:
    b = p.chromium.launch()
    ctx = b.new_context(viewport={'width': 390, 'height': 800}); ctx.add_init_script("sessionStorage.setItem('q_splash_done','1'); localStorage.setItem('q_intro_done','1')")
    page = ctx.new_page(); watch(page, 'SELLER'); route_block(page)
    page.goto(f'http://localhost:8099/?groupId={gid}&role=SELLER', wait_until='load'); page.wait_for_timeout(600)
    emit(page, 'init-state', fx['init']); emit(page, 'seller-account-state', ACCT); emit(page, 'incoming-list', {'groupId': gid, 'incoming': INC}); emit(page, 'withdrawals-list', {'groupId': gid, 'withdrawals': WD})
    emit(page, 'receiving-details', fx['detailsUSD']); page.wait_for_timeout(300)
    page.evaluate("() => { const o = document.getElementById('onboardingOverlay'); if (o) o.remove(); openTxAccountView(); }"); page.wait_for_timeout(400)

    print('\nA. Home in the bank style (phone)')
    ok(page.evaluate("() => document.documentElement.dataset.wp") == '4', 'Summit (4) is the default wallpaper')
    t = page.inner_text('#v41Home')
    ok(page.is_visible('.v41-bal') and 'Available balance' in t and '$100,000.00' in page.inner_text('#v41Amount'), 'balance card shows Available balance $100,000.00')
    ok('$100,020.00' in page.inner_text('.v41-bal .mm2') and '$20.00' in page.inner_text('.v41-bal .mm2'), 'Money in $100,020.00 and Money out $20.00 on the card')
    st = page.inner_text('.v41-stats').replace('\n', ' ')
    ok('Total deposited' in st and '$100,020.00' in st and 'Fees paid' in st and '$20.00' in st and 'Card issuing fee' in st, 'Total deposited $100,020.00 and Fees paid $20.00 (card fee)')
    ok('Withdrawn' in st and 'Held in vault' in st and 'Nothing in review' in st and 'No withdrawals yet' in st, 'Withdrawn and Held in vault show their status lines')
    ok('•••• 7765' in page.inner_text('.v41-bal .bf'), 'the card footer shows the account number (last 4) because bank details exist')
    acts = page.inner_text('.v41-actions').replace('\n', ' ')
    ok(all(w in acts for w in ('Send', 'Receive', 'Withdraw', 'Statements')), 'quick actions: Send, Receive, Withdraw, Statements')
    ok(not page.is_visible('#txCardTile') and not page.is_visible('#txActionRow') and not page.is_visible('.tx-stats-row'), 'the old tiles are gone from Home; the virtual card has its own page')
    ok(page.locator('#txSupportBtn').count() == 0 and page.locator('#txBellBtn').count() == 0, 'no Support / bell in the top bar')
    ok(page.is_visible('#txFlagChip') and page.is_visible('#txChatPill') and page.is_visible('#txAvatar') and page.is_visible('.v41-menu') and 'Kwame' in page.inner_text('#v41Hello'), 'top bar: avatar + greeting, Chat, country flag, menu')
    r = page.inner_text('#v41Recent')
    ok('AIRWX card issuing fee' in r and 'Withdrawal' in r and 'Payment from Acme Ltd' in r and '−$20.00' in r and '−$500.00' in r and '+$100,020.00' in r, 'recent activity lists the payment, the withdrawal and the fee with signs')
    ok(page.evaluate("() => document.documentElement.scrollWidth <= innerWidth + 1"), 'no horizontal scroll on a phone')
    shot(page, 'v41_home_phone')
    page.click('#v41Eye'); page.wait_for_timeout(100)
    ok('$100,000.00' not in page.inner_text('#v41Amount') and '•' in page.inner_text('#v41Amount') and '7765' not in page.inner_text('.v41-bal .bf'), 'the eye hides the balance and the account digits')
    page.reload(); page.wait_for_timeout(500)
    emit(page, 'init-state', fx['init']); emit(page, 'seller-account-state', ACCT); page.evaluate("() => { const o = document.getElementById('onboardingOverlay'); if (o) o.remove(); openTxAccountView(); }"); page.wait_for_timeout(300)
    ok('•' in page.inner_text('#v41Amount'), 'the hidden state is remembered')
    page.click('#v41Eye'); ok('$100,000.00' in page.inner_text('#v41Amount'), 'and shows again with another tap')
    emit(page, 'incoming-list', {'groupId': gid, 'incoming': INC}); emit(page, 'withdrawals-list', {'groupId': gid, 'withdrawals': WD}); emit(page, 'receiving-details', fx['detailsUSD']); page.wait_for_timeout(200)
    # an account with no bank details yet uses the Account ID
    emit(page, 'receiving-details', {'approved': True, 'ready': False, 'currency': 'USD'}); page.wait_for_timeout(120)
    ok('ID •••• 7765' in page.inner_text('.v41-bal .bf'), 'no bank details yet: the card footer uses the Account ID')
    emit(page, 'receiving-details', fx['detailsUSD']); page.wait_for_timeout(120)

    print('\nB. Actions and bottom bar')
    page.click('#v41Home .v41-act:has-text("Receive")'); ok(page.is_visible('#txPageAccounts'), 'Receive opens the account details')
    page.click('#txBottomNav [data-bn=dashboard]'); page.click('#v41Home .v41-act:has-text("Withdraw")'); ok(page.is_visible('#txPageWithdraw'), 'Withdraw opens the withdrawal page')
    page.click('#txBottomNav [data-bn=dashboard]'); page.click('#v41Home .v41-act:has-text("Statements")'); ok(page.is_visible('#txPageStatements'), 'Statements opens the statements page')
    page.click('#txBottomNav [data-bn=dashboard]'); clear(page); page.click('#v41Home .v41-act:has-text("Send")'); page.wait_for_timeout(150); ok(page.is_visible('#depositWizard') and len(sent(page, 'get-deposit-wallets')) == 1, 'Send opens the deposit wizard')
    page.evaluate("() => closeDepositWizard()")
    page.click('#txBottomNav [data-bn=transfer]'); ok(page.is_visible('#txPageTransfer') and 'Add money' in page.inner_text('#txPageTransfer') and 'Withdraw' in page.inner_text('#txPageTransfer'), 'Transfer: Send, Add money, Withdraw')
    page.click('#txBottomNav [data-bn=card]'); ok(page.is_visible('#txPageCard') and 'Cards' in page.inner_text('#txPageCard h1'), 'Cards: the virtual card has its own page')
    ok(page.locator('#txBottomNav button.active').inner_text().strip() == 'Cards', 'the bottom bar highlights Cards')
    page.click('#txBottomNav [data-bn=transactions]'); ok(page.is_visible('#txPageTransactions') and 'Money in' in page.inner_text('#v41ActSum') and page.locator('#v41ActAll .v41-item').count() == 3, 'Activity: Money in / Money out and the whole list')
    ok(page.locator('#v41ActSum .pos').inner_text() == '$100,020.00' and page.locator('#v41ActSum .neg').inner_text() == '$20.00', 'Activity totals agree with Home')
    shot(page, 'v41_activity_phone')
    page.click('#txBottomNav [data-bn=accounts]') if page.locator('#txBottomNav [data-bn=accounts]').count() else None

    print('\nC. Transaction details')
    page.click('#txBottomNav [data-bn=dashboard]')
    page.click('#v41Recent .v41-item:has-text("Payment from")'); page.wait_for_timeout(450)
    s = page.inner_text('#v41Sheet')
    ok(page.evaluate("() => document.getElementById('v41Sheet').classList.contains('on')") and 'Completed' in s and 'IN-1001' in s and 'Acme Ltd' in s and 'Account number ••7765' in s, 'the payment sheet shows status, reference, payer and the account number it landed in')
    ok(page.locator('#v41Sheet a:has-text("Download receipt")').count() == 1, 'with a receipt download')
    shot(page, 'v41_sheet_phone')
    page.keyboard.press('Escape'); page.wait_for_timeout(350); ok(not page.evaluate("() => document.getElementById('v41Sheet').classList.contains('on')"), 'Escape closes it')
    page.click('#v41Recent .v41-item:has-text("Withdrawal")'); page.wait_for_timeout(450)
    s = page.inner_text('#v41Sheet'); ok('In progress' in s and 'WD-1' in s and '•••• 9012' in s and '123456789012' not in s, 'a withdrawal shows In progress, its reference and a masked destination')
    page.click('#v41SheetBg', position={'x': 10, 'y': 10}); page.wait_for_timeout(350)
    ok(not page.evaluate("() => document.getElementById('v41Sheet').classList.contains('on')"), 'tapping outside closes it')

    print('\nD. Side list keeps every option and ends with Sign out')
    page.evaluate("() => toggleTxSidebar()"); page.wait_for_timeout(400)
    labels = page.evaluate("() => [...document.querySelectorAll('.tx-sidebar .tx-nav-item')].map(b => b.textContent.replace(/\\s+/g,' ').trim())")
    want = ['Chat room', 'Dashboard', 'Accounts', 'Card', 'Transactions', 'Withdraw', 'Statements', 'Forms', 'Security', 'Notifications', 'Profile', 'Help & Support', 'Back to chat room', 'Sign out']
    ok(all(any(l.startswith(w) for l in labels) for w in want), 'all options are there: ' + ' | '.join(labels))
    ok(labels[-1].startswith('Sign out') and labels[-2].startswith('Back to chat room'), 'Sign out is the last item, under "Back to chat room"')
    so = box(page, '#txSignOut'); ok(so['b'] <= 800 and so['y'] > 300, 'Sign out is visible at the bottom of the list on a phone')
    top = page.evaluate("([x,y]) => { const e = document.elementFromPoint(x,y); return !!e && !!e.closest('#txSignOut') }", [so['x'] + so['w'] / 2, so['y'] + so['h'] / 2]); ok(top, 'and nothing covers it')
    shot(page, 'v41_side_phone')
    page.click('#txSignOut'); page.wait_for_timeout(200)
    ok(page.is_visible('#genericModal') and 'Sign out' in page.inner_text('#genericModal'), 'Sign out asks for confirmation')
    page.evaluate("() => { sessionStorage.setItem('q_session_token', 'tok-abc'); }")
    with page.expect_navigation(timeout=5000):
        page.click('#genericModalConfirmBtn')
    page.wait_for_timeout(500)
    ok(page.url.rstrip('/').endswith(':8099') and 'groupId' not in page.url, 'confirming returns to the app start (no group link)')
    ok(page.evaluate("() => sessionStorage.getItem('q_session_token')") != 'tok-abc', 'the session token is gone')
    ok(page.is_visible('#appGate') and page.is_visible('#gvWelcome') and not page.is_visible('#txAccountView'), 'the person lands on Sign in / Create account')

    print('\nE. Profile photo')
    page.goto(f'http://localhost:8099/?groupId={gid}&role=SELLER', wait_until='load'); page.wait_for_timeout(500)
    emit(page, 'init-state', fx['init']); emit(page, 'seller-account-state', ACCT); emit(page, 'receiving-details', fx['detailsUSD']); page.evaluate("() => { const o = document.getElementById('onboardingOverlay'); if (o) o.remove(); openTxAccountView(); }"); page.wait_for_timeout(300)
    ok(any(x['groupId'] == gid for x in sent(page, 'get-my-photo')), 'the saved photo is requested')
    page.click('#txBottomNav [data-bn=profile]'); page.wait_for_timeout(200)
    t = page.inner_text('#txPageProfile'); ok('KM' in page.inner_text('#v41PickPhoto') and 'Account number' in t and 'Account ID' in t, 'Profile shows initials until a photo is added, plus the Account ID and the account number rows')
    ok('4821907765' not in page.inner_text('#txProfileAcctNo') and '7765' in page.inner_text('#txProfileAcctNo'), 'the account number is masked (••••7765)')
    page.click('#v41AcctNoEye'); ok('4821907765' in page.inner_text('#txProfileAcctNo'), 'the eye reveals it')
    page.click('#txBottomNav [data-bn=dashboard]'); page.click('#txBottomNav [data-bn=profile]'); ok('4821907765' not in page.inner_text('#txProfileAcctNo'), 'and it hides again after leaving the page')
    ok(page.locator('#txPageProfile .v41-signout-row').count() == 1, 'Profile ends with a Sign out button')
    open('/tmp/pic.png', 'wb').write(PNG); clear(page)
    page.set_input_files('#v41File', '/tmp/pic.png'); page.wait_for_timeout(600)
    ph = sent(page, 'set-my-photo')
    ok(len(ph) == 1 and ph[0]['groupId'] == gid and ph[0]['photo'].startswith('data:image/jpeg;base64,/9j/'), 'choosing a picture crops it to a small JPEG and saves it to the account')
    ok(page.evaluate("() => document.getElementById('txAvatar').classList.contains('has') && document.getElementById('v41PickPhoto').classList.contains('has')") and 'url(' in page.evaluate("() => document.getElementById('txAvatar').style.backgroundImage"), 'the photo replaces the initials in the top bar and on the profile')
    ok(page.is_visible('#v41RemovePhoto'), 'a Remove photo link appears')
    shot(page, 'v41_profile_photo')
    clear(page); page.click('#v41RemovePhoto'); ok(sent(page, 'set-my-photo')[0]['photo'] is None and not page.evaluate("() => document.getElementById('txAvatar').classList.contains('has')"), 'removing it brings the initials back')
    emit(page, 'my-photo', {'photo': 'data:image/jpeg;base64,/9j/AAAA'}); page.wait_for_timeout(100)
    ok(page.evaluate("() => document.getElementById('txAvatar').classList.contains('has')"), 'a photo saved on another device appears here')
    emit(page, 'photo-result', {'ok': False, 'error': 'Please choose a JPG or PNG picture.'}); page.wait_for_timeout(150)
    ok('JPG or PNG' in page.inner_text('#toastContainer'), 'a refused picture shows the reason')

    print('\nF. Desktop')
    p2 = b.new_context(viewport={'width': 1280, 'height': 800}); p2.add_init_script("sessionStorage.setItem('q_splash_done','1'); localStorage.setItem('q_intro_done','1')")
    d = p2.new_page(); watch(d, 'DESKTOP'); route_block(d)
    d.goto(f'http://localhost:8099/?groupId={gid}&role=SELLER', wait_until='load'); d.wait_for_timeout(500)
    emit(d, 'init-state', fx['init']); emit(d, 'seller-account-state', ACCT); emit(d, 'incoming-list', {'groupId': gid, 'incoming': INC}); emit(d, 'receiving-details', fx['detailsUSD'])
    d.evaluate("() => { const o = document.getElementById('onboardingOverlay'); if (o) o.remove(); openTxAccountView(); }"); d.wait_for_timeout(400)
    sb, bal = box(d, '.tx-sidebar'), box(d, '.v41-bal')
    ok(sb['w'] > 200 and bal['x'] > sb['r'] and bal['w'] <= 660 and bal['w'] > 400, 'sidebar on the left, balance card in a centred column')
    ok(d.is_visible('#txSignOut') and d.is_visible('#txChatPill') and 'Chat room' in d.inner_text('#txChatPill'), 'Sign out and the Chat room button are visible')
    shot(d, 'v41_home_desktop')
    d.close()

    print('\nG. Desk Officer sign-in page')
    o = b.new_context(viewport={'width': 1100, 'height': 760}); o.add_init_script("sessionStorage.setItem('q_splash_done','1')")
    op = o.new_page(); watch(op, 'OFFICER'); route_block(op)
    op.goto('http://localhost:8099/?officer=1', wait_until='load'); op.wait_for_timeout(700)
    ok(op.is_visible('#officerGate') and 'desk officer console' in op.inner_text('#officerGate').lower() and 'restricted access' in op.inner_text('#officerGate').lower(), 'its own page: "Desk Officer Console · Restricted access"')
    g = op.inner_text('#officerGate')
    ok(op.locator('#appGate').count() == 0 and 'Create account' not in g and 'Take the tour' not in g and 'Download the app' not in g and 'Welcome' not in g, 'nothing like the client screen: no Create account, tour, download or Welcome')
    ok(not op.is_visible('#appShell') and len(sent(op, 'join-room')) == 0, 'the workspace is hidden and nothing joins a room before a passkey is entered')
    shot(op, 'v41_officer')
    op.click('#ogBtn'); ok('Enter your administrator passkey' in op.inner_text('#ogMsg') and len(sent(op, 'join-room')) == 0, 'an empty passkey is refused locally')
    op.fill('#ogKey', 'wrong-key'); op.press('#ogKey', 'Enter'); op.wait_for_timeout(200)
    jr = sent(op, 'join-room'); ok(len(jr) == 1 and jr[0]['adminKey'] == 'wrong-key' and jr[0]['role'] == 'ADMINISTRATOR', 'the passkey is sent as an administrator join')
    emit(op, 'init-state', {**fx['init'], 'isAdminConfirmed': False}); op.wait_for_timeout(300)
    ok('not recognised' in op.inner_text('#ogMsg') and op.is_visible('#officerGate'), 'a wrong passkey: clear message, the page stays')
    ok(op.input_value('#ogKey') == '', 'and the field is cleared for another try')
    op.click('#ogEye'); ok(op.get_attribute('#ogKey', 'type') == 'text', 'the eye shows the passkey')
    op.fill('#ogKey', 'right-key'); op.click('#ogBtn'); op.wait_for_timeout(150)
    emit(op, 'init-state', {**fx['init'], 'isAdminConfirmed': True, 'adminRole': 'SUPER_ADMIN'}); op.wait_for_timeout(400)
    ok(op.locator('#officerGate').count() == 0 and op.is_visible('#appShell'), 'the right passkey opens the Desk')
    o.close()
    o2 = b.new_context(viewport={'width': 390, 'height': 740}); op2 = o2.new_page(); route_block(op2)
    op2.goto('http://localhost:8099/?officer=1', wait_until='load'); op2.wait_for_timeout(500)
    emit(op2, 'room-closed', {'reason': 'removed', 'hasAccount': False, 'needLogin': True}); op2.wait_for_timeout(300)
    ok(op2.locator('#appGate').count() == 0 and op2.is_visible('#officerGate'), 'even if the default group is gone, the officer page never turns into the client welcome screen')
    ok(op2.evaluate("() => document.documentElement.scrollWidth <= innerWidth + 1"), 'the officer page fits a phone')
    o2.close()

    print('\nH. Everything quiet')
    ok(not errors, 'no JavaScript errors: ' + str(errors))
    b.close()
print(f'\nRESULT: {passed} passed, {failed} failed'); sys.exit(1 if failed else 0)
